from pathlib import Path
import json
D=Path('src/lib/conocimiento')
def save(n,v): (D/n).write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n')
raw='''sumer|Sumer|Mesopotamia meridional|-3500|-2000|Urbanización y predominio de ciudades sumerias; no fecha de origen o desaparición de una población.|Ciudades-Estado con autoridades palaciales y religiosas; sus relaciones variaron entre competencia, alianzas y hegemonías.|Agricultura irrigada, ganadería y comercio con regiones sin los mismos recursos minerales y forestales.|Escritura cuneiforme, contabilidad, medición y tradiciones literarias transmitidas y reformuladas después.|Instituciones urbanas y registros administrativos influyeron en culturas mesopotámicas posteriores.|No reducir todas las ciudades a un modelo de teocracia inmutable ni explicar el Estado solo por el riego.|31.32|45.64|iq|hist,unesco
egipto|Egipto faraónico|Valle del Nilo|-3100|-30|Intervalo convencional entre unificación dinástica y conquista romana; incluye rupturas y dominaciones externas.|Monarquía y administración territorial con cambios en poder provincial, templos y relaciones exteriores.|Agricultura del valle y del delta, obras hidráulicas, producción artesanal y redes de intercambio.|Escrituras jeroglífica e hierática, prácticas médicas, astronomía calendárica y arquitectura monumental.|Paisajes funerarios, textos y técnicas permiten estudiar interacción entre poder, religión y trabajo.|No presentar tres milenios como una cultura sin cambios ni atribuir toda construcción a trabajo esclavo.|25.72|32.66|eg|hist,unesco
indo|Tradición urbana del Indo|Asia meridional|-2600|-1900|Fase urbana madura; continuidades y transformaciones exceden estos límites.|Asentamientos con estándares constructivos y planificación; no hay consenso sobre una monarquía única o su estructura completa.|Agricultura, ganadería, artesanías y redes terrestres y marítimas que alcanzaban otras regiones.|Pesos, sellos, drenajes y planificación; escritura no descifrada de manera consensuada.|Ofrece un caso de urbanismo complejo cuyo poder político se investiga sobre todo arqueológicamente.|No deducir ausencia de jerarquía de la falta de palacios identificados ni afirmar traducciones seguras de sus signos.|27.33|68.14|pk,in|hist,unesco
shang|Shang|China septentrional|-1600|-1046|Cronología aproximada para una tradición dinástica apoyada en arqueología y textos oraculares.|Centros reales, linajes y redes de autoridad con rituales y actividad militar.|Agricultura, ganadería y producción especializada de bronces dentro de redes regionales.|Inscripciones en huesos oraculares y complejas técnicas de fundición.|Permite contrastar secuencias dinásticas tradicionales con restos y escrituras contemporáneas.|Las fechas tempranas y extensión efectiva son discutidas; no equivale a toda la población de la China actual.|36.1|114.35|cn|hist,unesco
han|Han|Asia oriental|-202|220|Incluye la interrupción Xin y divisiones internas; rango convencional de comparación.|Administración imperial con burocracia, territorios y negociaciones con poderes regionales.|Agricultura fiscalizada, artesanías, comercio y circulación de bienes por rutas diversas.|Historiografía, prácticas administrativas y desarrollos técnicos, con variación entre regiones.|Modelos de organización imperial y tradiciones textuales tuvieron larga influencia regional.|No confundir influencia cultural con control territorial continuo ni identidad moderna con una dinastía antigua.|34.34|108.94|cn|hist,unesco
grecia|Mundos griegos arcaicos y clásicos|Mediterráneo y mar Negro|-800|-323|Recorte de períodos arcaico y clásico; las culturas griegas continuaron en época helenística y romana.|Poleis con gobiernos diversos: oligarquías, tiranías, democracias y reinos coexistieron.|Agricultura, navegación, artesanía, comercio y trabajo libre y esclavizado.|Debate filosófico, teatro, matemáticas e historiografía en contacto con otras tradiciones.|Instituciones y textos fueron reinterpretados repetidamente, no transmitidos de forma intacta.|No identificar a todos los griegos con la democracia ateniense ni invisibilizar exclusiones de género y condición jurídica.|37.98|23.73|gr,tr,it|hist,unesco
roma|Roma republicana e imperial|Mediterráneo|-509|476|La fundación republicana es tradicional; 476 limita Occidente, no toda continuidad romana.|República oligárquica y después variadas formas imperiales; ciudadanía y administración cambiaron a lo largo del tiempo.|Agricultura, tributos, comercio y trabajo bajo condiciones jurídicas muy diversas, incluida esclavitud.|Derecho, ingeniería, urbanismo y compilación de saberes mediterráneos.|Infraestructuras, lenguas y tradiciones jurídicas persistieron mediante adaptaciones regionales.|La caída no fue un evento único y el Imperio romano de Oriente continuó muchos siglos.|41.9|12.5|it,gr,tr,eg|hist,unesco
persia|Imperio aqueménida|Asia occidental|-550|-330|Período imperial aproximado desde Ciro hasta la conquista macedónica.|Monarquía imperial con satrapías y acuerdos con élites locales; diversidad de lenguas y tradiciones.|Tributación, agricultura y circulación mediante redes terrestres y centros administrativos.|Registros multilingües y arquitectura que integraba técnicas y trabajo de distintos territorios.|Su organización muestra cómo se gobierna diversidad sin imponer uniformidad cultural completa.|Fuentes griegas y reales tienen sesgos distintos; no reconstruir el imperio con una sola voz.|29.94|52.89|ir,iq,tr|hist,unesco
aksum|Aksum|Cuerno de África|100|700|Fase de protagonismo político y comercial; los cambios se extendieron más allá del intervalo.|Reino conectado con regiones vecinas y rutas del mar Rojo, con transformaciones religiosas y políticas.|Agricultura y comercio en redes que enlazaban África, Arabia y el mundo mediterráneo.|Monedas, inscripciones, arquitectura monumental y tradición escrita en geez.|Es central para comprender historias africanas y del océano Índico conectadas, no aisladas.|No explicar su transformación únicamente por un cambio de rutas ni equiparar reino antiguo y fronteras actuales.|14.13|38.72|et,er|hist,unesco
mali|Mali imperial|África occidental|1235|1600|Fechas aproximadas de consolidación y fragmentación; continuidades políticas y culturales posteriores.|Autoridad imperial negociada con poderes locales y redes regionales de ciudades y territorios.|Agricultura, ganadería, oro y comercio transahariano con trabajo y distribución desiguales.|Tradiciones orales, enseñanza y manuscritos en centros conectados con el mundo islámico.|Permite estudiar redes intelectuales africanas junto a instituciones y economías regionales.|No reducir Mali a la riqueza de un gobernante ni tratar relatos orales como simples copias de fuentes escritas.|12.65|-8|ml,sn,gn|hist,unesco
angkor|Angkor|Sudeste asiático|802|1431|Convención para un período, no fecha de desaparición de la sociedad jemer.|Redes de poder real, templos y asentamientos con cambios de centro y autoridad.|Agricultura de arroz, obras hidráulicas e intercambio en territorios conectados.|Arquitectura, ingeniería del agua, epigrafía y adaptación de tradiciones religiosas.|El paisaje urbano y sus reservorios permiten estudiar relación entre ambiente y organización social.|No atribuir su transformación a una única sequía o invasión ni ignorar continuidad de uso y memoria.|13.41|103.87|kh|hist,unesco
maya|Ciudades mayas del período Clásico|Mesoamérica|250|900|Período Clásico convencional; los pueblos mayas existen antes y después y continúan hoy.|Entidades políticas y dinastías diversas, no un único imperio maya centralizado.|Agricultura adaptada a ambientes distintos, intercambio y producción artesanal especializada.|Escritura, calendarios, matemáticas y observaciones astronómicas integradas en vida política y ritual.|Inscripciones y arqueología permiten historias locales detalladas y estudio de paisajes transformados.|El declive de algunas ciudades no equivale a desaparición de los mayas; evitar relatos de misterio sin evidencia.|17.22|-89.62|gt,mx,bz,hn|hist,unesco
teotihuacan|Teotihuacán|México central|100|650|Intervalo aproximado de gran desarrollo urbano; poblamiento y cambios exceden estas fechas.|Gran centro urbano con barrios y relaciones regionales; la estructura exacta de gobierno sigue debatida.|Agricultura regional, talleres, obsidiana e intercambios de amplio alcance.|Planificación urbana, arquitectura y producción mural con interpretaciones aún discutidas.|Su influencia arqueológica se rastrea sin suponer que todo objeto similar prueba conquista.|No identificar automáticamente idioma, etnicidad o régimen político de sus habitantes.|19.69|-98.84|mx|hist,unesco
inca|Tawantinsuyu|Andes|1438|1533|Período convencional de expansión imperial hasta la conquista y crisis dinástica; hubo resistencias posteriores.|Poder imperial articulado mediante autoridades locales, obligaciones laborales y redes administrativas.|Agricultura de múltiples pisos ecológicos, almacenamiento y redistribución con desigualdades territoriales.|Caminos, arquitectura, manejo agrario y registros mediante quipus.|El sistema vial y paisajes agrícolas documentan coordinación a gran escala en ambientes diversos.|No describirlo como sociedad sin registros por no usar escritura alfabética ni dar por concluida toda resistencia en 1533.|-13.52|-71.97|pe,bo,ec,cl,ar|hist,unesco
mexica|Triple Alianza y poder mexica|México central|1428|1521|Recorte de hegemonía de la Triple Alianza; no comienzo o final de las culturas nahuas.|Alianza de Tenochtitlan, Texcoco y Tlacopan con tributos y formas diversas de subordinación.|Agricultura intensiva, mercados, tributos y redes de abastecimiento de ciudades.|Códices, calendarios, obras hidráulicas y conocimientos vinculados a organización política y ritual.|El caso permite estudiar tributación y urbanismo a través de fuentes indígenas y coloniales contrastadas.|La conquista fue un proceso con múltiples actores indígenas; no una simple oposición binaria de europeos e indígenas.|19.43|-99.13|mx|hist,unesco
song|Song|Asia oriental|960|1279|Distingue fases septentrional y meridional; hubo importantes cambios territoriales.|Administración imperial, exámenes y élites regionales con negociación política y fiscal.|Agricultura intensiva, mercados urbanos, manufacturas y comercio marítimo y terrestre.|Impresión, conocimientos técnicos y desarrollos comerciales y monetarios.|Permite comparar expansión mercantil sin imponer categorías de industrialización europea posteriores.|No describir su economía como capitalismo moderno sin explicar criterios ni ignorar conflictos y desigualdades.|34.8|114.3|cn|hist,unesco'''
keys=['id','nombre','region','desde','hasta','cronologia','organizacion','subsistencia','conocimiento','legado','limite','lat','lng','paises','fuentes']
cs=[]
for line in raw.splitlines():
 v=line.split('|');assert len(v)==15,(len(v),line[:40]);c=dict(zip(keys,v))
 for k in ['desde','hasta']:c[k]=int(c[k])
 for k in ['lat','lng']:c[k]=float(c[k])
 for k in ['paises','fuentes']:c[k]=c[k].split(',')
 cs.append(c)
save('civilizaciones.json',cs)
