for line in raworg.splitlines():
 v=line.split('|');assert len(v)==10,(len(v),line[:35]);id,sigla,n,an,sede,mec,mech,lim,areas,url=v
 orgs.append(dict(id=id,sigla=sigla,nombre=n,anio=int(an),sede=sede,mandato=mec,mecanismo=mech,limite=lim,areas=areas.replace('urbanismo,vivienda','urbanismo,infraestructura').split(','),fuente='Sitio institucional · consultar instrumentos y documentación original',url=url))
